/// <summary>
/// designed from AVA
/// </summary>
[ExtensionOf(formStr(pricediscadm))]
final class AVAPriceDiscAdmFrm_Extension
{
}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_enableDeleteButton">_enableDeleteButton</param>
public void doActiveButtons(boolean _enableDeleteButton)
{
    next doActiveButtons(_enableDeleteButton);

    boolean hasNewAndClose;
    hasNewAndClose = PriceDiscAdmTrans::hasNewAndClosePos(callerpriceDiscAdmTable.JournalNum);
    priceDiscAdmCopy.enabled(!hasNewAndClose);

    if (callerpriceDiscAdmTable.Posted)
    {
        AVApriceDiscAdmEdit.enabled(false);
    }
    else
    {
        if (PriceDiscAdmTable::find(priceDiscAdmTrans.JournalNum).LockedForDeletion)
        {
            AVApriceDiscAdmEdit.enabled(false);
        }
        else
        {
            AVApriceDiscAdmEdit.enabled(true);
        }
    }
    deleteTradeAgreements.enabled(!hasNewAndClose);
}

/// <summary>
/// designed from AVA
/// </summary>
public void init()
{
    PriceDiscAdmTable       callerPriceDiscAdmTable;
    if (this.args().dataset() == tableNum(PriceDiscAdmTable)) 
    {
        callerpriceDiscAdmTable = this.args().record();
    }
    next init();

    PriceDiscAdmTrans_ds.object(fieldNum(PriceDiscAdmTrans,AVAGraduatedPrice)).enabled(callerPriceDiscAdmTable.DefaultRelation == PriceType::PricePurch);
    FormGridControl   gridControl = this.design().controlName('Grid');
    gridControl.visibleRows(20);
}
